// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 value) public {
        vm.assume(caller != c.owner());
        vm.deal(address(this), value);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: value}(abi.encodeWithSelector(c.withdrawAll.selector));
        assertTrue(!success);
    }
}

